<?php
declare(strict_types=1);
namespace Tests\Unit\QuestionLearning;
use App\Application\Performance\Port\TransactionManagerInterface;use App\Application\Performance\Service\CompleteAttemptService;use App\Domain\Performance\Entity\Answer;use App\Domain\Performance\Entity\Attempt;use App\Domain\Performance\Repository\AttemptRepositoryInterface;use App\Domain\QuestionLearning\Entity\LearningEvent;use App\Domain\QuestionLearning\Repository\CompletedAttemptLearningSignalReaderInterface;use App\Domain\QuestionLearning\Repository\LearningEventRepositoryInterface;use App\Domain\QuestionLearning\ValueObject\CompletedAttemptLearningSignal;use PHPUnit\Framework\TestCase;
final class CompleteAttemptLearningSignalTest extends TestCase { public function testRecordsImmutableOutcomeForEachSubject(): void { $attempts=new class implements AttemptRepositoryInterface { public function saveAttempt(Attempt $attempt):void{} public function findByIdForUser(string $id,string $user):?Attempt{return new Attempt('attempt-1','user-1','notebook-1','question-1',1,'STUDY',new \DateTimeImmutable('2026-01-01T00:00:00Z'));} public function nextNumber(string $u,string $n,string $q):int{return 1;} public function complete(string $id,string $answer,\DateTimeImmutable $at):bool{return true;} public function appendAnswer(Answer $answer):void{} public function listAnswers(string $id):array{return [new Answer('answer-1',$id,'option-a',1,37,new \DateTimeImmutable('2026-01-01T00:01:00Z'))];} }; $events=new class implements LearningEventRepositoryInterface { public array $events=[]; public function append(LearningEvent $event):void{$this->events[]=$event;} public function listForUserSubject(string $u,string $s,\DateTimeImmutable $since):array{return [];} }; $reader=new class implements CompletedAttemptLearningSignalReaderInterface { public function read(string $questionId,string $selectedOptionId,int $elapsedSeconds,string $origin):?CompletedAttemptLearningSignal{return new CompletedAttemptLearningSignal($questionId,$selectedOptionId,false,$elapsedSeconds,$origin,['subject-1','subject-2']);} public function taxonomySubjectIdsForQuestion(string $questionId):array{return ['subject-1','subject-2'];} }; $transactions=new class implements TransactionManagerInterface { public function transactional(callable $callback):mixed{return $callback();} }; (new CompleteAttemptService($attempts,$transactions,$reader,$events))->complete('user-1','attempt-1'); self::assertCount(2,$events->events); self::assertSame('ANSWER_COMPLETED',$events->events[0]->type->value); self::assertSame('INCORRECT',$events->events[0]->outcome?->value); self::assertSame(37,$events->events[0]->elapsedSeconds); self::assertSame('STUDY',$events->events[0]->origin); self::assertSame(['subject-1','subject-2'],array_map(static fn(LearningEvent $event)=>$event->taxonomySubjectId,$events->events)); } }
